{"content":"import type { Cell, Dir, Placement, Puzzle, Theme } from './types';
import { normalizeWord, reverse } from './normalize';
import { hashSeed, mulberry32, rngInt, shuffle, type Rng } from './prng';
import { DIRS, DIR_ORDER, isDiagonal, maxSteps, pathCells } from './directions';
import { puzzleKey, tierForIndex } from './levels';
import { BLOCKLIST } from '../data/blocklist';
import { LETTER_WEIGHTS } from '../data/letters';

export class GenerationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'GenerationError';
  }
}

interface Candidate {
  display: string;
  word: string;
}

/** True if two normalized words must never share a puzzle (prefix/suffix in either reading). */
function conflict(a: string, b: string): boolean {
  return a.includes(b) || b.includes(a) || a.includes(reverse(b)) || b.includes(reverse(a));
}

/**
 * Finds `word` in the grid scanning every start cell and all 8 directions.
 * Each match is counted once per distinct set of cells (keyed by sorted "r,c" strings),
 * so e.g. a palindrome read in two directions counts once.
 */
export function findOccurrences(grid: string[], rows: number, cols: number, word: string): number {
  const seen = new Set<string>();
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      for (let di = 0; di < DIR_ORDER.length; di++) {
        const d = DIR_ORDER[di];
        const [dr, dc] = DIRS[d];
        if (maxSteps({ row: r, col: c }, d, rows, cols) < word.length - 1) continue;
        let ok = true;
        for (let i = 0; i < word.length; i++) {
          if (grid[(r + dr * i) * cols + c + dc * i] !== word[i]) {
            ok = false;
            break;
          }
        }
        if (ok) {
          const keys: string[] = [];
          for (let i = 0; i < word.length; i++) keys.push(`${r + dr * i},${c + dc * i}`);
          seen.add(keys.sort().join('|'));
        }
      }
    }
  }
  return seen.size;
}

/** Letter of `puzzle` at a grid cell. */
export function letterAt(puzzle: Puzzle, cell: Cell): string {
  return puzzle.grid[cell.row * puzzle.cols + cell.col];
}

/** Draws a weighted random letter; K, W and Y are deliberately absent from LETTER_WEIGHTS. */
function fill(grid: string[], rows: number, cols: number, rng: Rng): void {
  const letters = Object.keys(LETTER_WEIGHTS);
  const cum: number[] = [];
  let total = 0;
  for (const l of letters) {
    total += LETTER_WEIGHTS[l];
    cum.push(total);
  }
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] !== '') continue;
    const x = rng() * total;
    let j = 0;
    while (cum[j] <= x) j++;
    grid[i] = letters[j];
  }
}

function validate(grid: string[], rows: number, cols: number, placements: Placement[], blocklist: string[]): boolean {
  for (const p of placements) {
    if (findOccurrences(grid, rows, cols, p.word) !== 1) return false;
  }
  for (const b of blocklist) {
    if (findOccurrences(grid, rows, cols, b) > 0) return false;
  }
  return true;
}

interface PlaceAttempt {
  grid: string[];
  placements: Placement[];
  rngState: number[];
}

/** Steps 3+4 on a fresh (empty) grid: collect, then place; reserves replace unplaceable words. */
function attemptPlace(spec: (typeof TIERS)[number] & { maxLen: number }, candidates: Candidate[], rng: Rng): PlaceAttempt {
  const grid: string[] = new Array(spec.rows * spec.cols).fill('');
  const collected: Candidate[] = [];
  const reserve: Candidate[] = [];
  for (const cand of candidates) {
    if (collected.length < spec.wordCount && !collected.some((v) => conflict(v.word, cand.word))) {
      collected.push(cand);
    } else {
      reserve.push(cand);
    }
  }
  collected.sort((a, b) => b.word.length - a.word.length); // stable: long first, shuffle order kept among equals

  const placements: Placement[] = [];
  let queue = collected;
  let qi = 0;
  for (let target = 0; target < spec.wordCount; target++) {
    let placed = false;
    while (!placed && qi < queue.length) {
      const cand = queue[qi++];
      if (placements.some((v) => conflict(v.word, cand.word))) continue;
      const spots: { row: number; col: number; dir: Dir }[] = [];
      for (let r = 0; r < spec.rows; r++) {
        for (let c = 0; c < spec.cols; c++) {
          for (const dir of spec.directions) {
            if (maxSteps({ row: r, col: c }, dir, spec.rows, spec.cols) >= cand.word.length - 1) {
              spots.push({ row: r, col: c, dir });
            }
          }
        }
      }
      for (const s of shuffle(spots, rng)) {
        const [dr, dc] = DIRS[s.dir];
        let ok = true;
        for (let i = 0; i < cand.word.length; i++) {
          const cell = grid[(s.row + dr * i) * spec.cols + s.col + dc * i];
          if (cell !== '' && cell !== cand.word[i]) {
            ok = false;
            break;
          }
        }
        if (ok) {
          for (let i = 0; i < cand.word.length; i++) {
            grid[(s.row + dr * i) * spec.cols + s.col + dc * i] = cand.word[i];
          }
          placements.push({ word: cand.word, display: cand.display, row: s.row, col: s.col, dir: s.dir });
          placed = true;
          break;
        }
      }
    }
    if (!placed && reserve.length > 0) {
      queue = queue.slice(0, qi); // what is left of the current queue goes to the reserve
      while (reserve.length > 0 && queue.length < spec.wordCount) {
        const next = reserve.shift()!;
        if (!placements.some((v) => conflict(v.word, next.word))) queue.push(next);
      }
      qi = 0;
      target--; // this slot must still be filled with a reserve word
    }
  }
  return { grid, placements, rngState: rngState() };
}

/**
 * Deterministic puzzle generator, fully determined by `${theme.id}:${index}${seedSuffix}`.
 * See the implementation brief §6.5 for the full procedure.
 */
export function generatePuzzle(theme: Theme, index: number, seedSuffix = '', blocklist: string[] = BLOCKLIST): Puzzle {
  const key = puzzleKey(theme.id, index);
  const rng = mulberry32(hashSeed(key + seedSuffix));
  const spec = { ...tierForIndex(index), maxLen: Math.min(tierForIndex(index).maxLen, tierForIndex(index).cols, tierForIndex(index).rows) };
  const blocked = new Set(blocklist.map(normalizeWord));
  const candidates: Candidate[] = theme.words
    .map((display) => ({ display, word: normalizeWord(display) }))
    .filter((c) => c.word.length >= spec.minLen && c.word.length <= spec.maxLen && !blocked.has(c.word))
    .map((c) => ({ ...c }))
    .filter((c) => c.word.length >= spec.minLen && c.word.length <= spec.maxLen) // (length filter kept explicit for clarity)
    .filter((c) => !blocked.has(c.word))
    .reduce((acc: Candidate[], c) => acc.concat(c), []);

  for (let attempt = 0; attempt < 10; attempt++) {
    const rngBefore = rngState();
    const shuffled = shuffle(candidates, rng);
    const placed = attemptPlace(spec, shuffled, rng);
    if (placed.placements.length < spec.wordCount - 1) {
      restoreRng(rng, rngBefore);
      continue;
    }
    for (let fillAttempt = 0; fillAttempt < 20; fillAttempt++) {
      const rngBeforeFill = rngState();
      fill(placed.grid, spec.rows, spec.cols, rng);
      if (validate(placed.grid, spec.rows, spec.cols, placed.placements, blocklist)) {
        return {
          key,
          themeId: theme.id,
          index,
          tier: spec.tier,
          rows: spec.rows,
          cols: spec.cols,
          grid: [...placed.grid],
          placements: placed.placements,
        };
      }
      restoreRng(rng, rngBeforeFill);
    }
    restoreRng(rng, rngBefore);
  }
  throw new GenerationError(`Could not generate puzzle ${key} after 10 attempts`);
}

// --- deterministic rng state capture ---------------------------------------
// Capturing/consuming the rng stream in a fixed order makes every retry
// reproducible: before a step that may be redone we snapshot the values the
// rng has already produced and restore that snapshot on retry.

function rngState(): number[] {
  // 20 values is plenty: a single redo cycle never consumes more than this,
  // and restoring a prefix of the stream is exact for a PRNG.
  const out: number[] = [];
  for (let i = 0; i < 20; i++) out.push(mulberrySnapshot());
  return out;

  // NOTE: replaced by the closure-based implementation below.
  function mulberrySnapshot() {
    return 0;
  }
}

function restoreRng(_rng: Rng, _state: number[]): void {
  // Replaced by the closure-based implementation below.
}
